import type {
  Article,
  CardSet,
  CompetitiveEvent,
  DeckArchetype,
  Rotation,
} from "@prize-map/types";

/** Generated by build.ts. The declaration gives consumers the stable content contract. */
export declare const posts: readonly Article[];
/** Every archetype the Deck Dex knows, in data/decks.yaml order. */
export declare const decks: readonly DeckArchetype[];
/** Oldest legal date first. */
export declare const sets: readonly CardSet[];
/** Oldest first. */
export declare const rotations: readonly Rotation[];
/** Soonest first. */
export declare const events: readonly CompetitiveEvent[];
